/**
 * Admin Dashboard - Main Wrapper
 * Routes to all admin management modules
 */

import React, { useState } from 'react';
import { Link, Routes, Route, useLocation } from 'react-router-dom';
import './AdminStyles.css';

// Import admin subcomponents
import AdminUsers from './AdminUsers';
import AdminAnalytics from './AdminAnalytics';
import AdminRefunds from './AdminRefunds';
import AdminCoupons from './AdminCoupons';
import AdminWallet from './AdminWallet';
import AdminReports from './AdminReports';

// Import legacy dashboard
import AdminDashboardLegacy from './AdminDashboardLegacy';

const AdminDashboard = () => {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const location = useLocation();

  const navigationItems = [
    { path: '/admin', label: 'Dashboard', icon: '📊' },
    { path: '/admin/users', label: 'Users', icon: '👥' },
    { path: '/admin/analytics', label: 'Analytics', icon: '📈' },
    { path: '/admin/refunds', label: 'Refunds', icon: '💳' },
    { path: '/admin/coupons', label: 'Coupons', icon: '🎟️' },
    { path: '/admin/wallet', label: 'Wallet', icon: '💰' },
    { path: '/admin/reports', label: 'Reports', icon: '📄' },
  ];

  const isActive = (path) => {
    return location.pathname === path || (path !== '/admin' && location.pathname.startsWith(path));
  };

  return (
    <div className="admin-dashboard">
      {/* Sidebar Navigation */}
      <aside className={`admin-sidebar ${sidebarOpen ? 'open' : 'closed'}`}>
        <div className="sidebar-header">
          <div className="sidebar-logo">
            <span className="logo-icon">⚙️</span>
            {sidebarOpen && <span className="logo-text">Admin</span>}
          </div>
          <button className="sidebar-toggle" onClick={() => setSidebarOpen(!sidebarOpen)}>
            {sidebarOpen ? '◀' : '▶'}
          </button>
        </div>

        <nav className="sidebar-nav">
          {navigationItems.map((item) => (
            <Link
              key={item.path}
              to={item.path}
              className={`nav-item ${isActive(item.path) ? 'active' : ''}`}
              title={!sidebarOpen ? item.label : ''}
            >
              <span className="nav-icon">{item.icon}</span>
              {sidebarOpen && <span className="nav-label">{item.label}</span>}
            </Link>
          ))}
        </nav>

        <div className="sidebar-footer">
          <Link to="/" className="nav-item back-link">
            <span className="nav-icon">🏠</span>
            {sidebarOpen && <span className="nav-label">Back to Home</span>}
          </Link>
        </div>
      </aside>

      {/* Main Content */}
      <main className="admin-main">
        <div className="admin-content">
          <Routes>
            <Route path="/" element={<AdminDashboardLegacy />} />
            <Route path="/users" element={<AdminUsers />} />
            <Route path="/analytics" element={<AdminAnalytics />} />
            <Route path="/refunds" element={<AdminRefunds />} />
            <Route path="/coupons" element={<AdminCoupons />} />
            <Route path="/wallet" element={<AdminWallet />} />
            <Route path="/reports" element={<AdminReports />} />
          </Routes>
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;
